/* eslint-disable */
// Generated by zotero-plugin-scaffold
// The in-page test runner, powered by the Vitest runtime (see vitest-runtime.js).
import {
  expect, vi, assert,
  describe, it, test, suite,
  beforeEach, afterEach, beforeAll, afterAll,
  startTests,
} from "./vitest-runtime.js";

// Minimal Vitest worker state.
// `vi.useFakeTimers`, `expect.poll` and snapshots read from `__vitest_worker__`.
// Fields are only filled in when missing, so an existing state (e.g. when this
// page is loaded inside a running Vitest worker) is not clobbered.
// Module mocking (`vi.mock`) requires Vite's transform pipeline and is not
// supported inside Zotero.
globalThis.__vitest_worker__ ??= {};
const workerState = globalThis.__vitest_worker__;
workerState.config ??= {};
workerState.config.fakeTimers ??= {};
workerState.config.expect ??= {};
workerState.config.expect.poll ??= {};
workerState.config.snapshotOptions ??= { expand: false };

// Expose globals so test files can use the classic globals style, like mocha.
Object.assign(window, {
  describe, it, test, suite,
  beforeEach, afterEach, beforeAll, afterAll,
  expect, vi, assert,
});

async function send(data) {
  const req = await Zotero.HTTP.request(
    "POST",
    "http://localhost:__PORT__/update",
    {
      body: JSON.stringify(data),
    }
  );

  if (req.status !== 200) {
    dump("Error sending data to server" + req.responseText);
    return null;
  } else {
    const result = JSON.parse(req.responseText);
    return result;
  }
}

window.debug = function (data) {
  send({ type: "debug", data });
};

let passed = 0,
  failed = 0,
  aborted = false;

function dump(str) {
  document.querySelector("#mocha").innerText += str;
}

// Counts the suites above the given task (the file task is the root).
// Tasks reference their parent suite via `task.suite`.
function suiteDepth(task) {
  let depth = 0;
  let current = task.suite;
  while (current && current.type !== "file") {
    depth++;
    current = current.suite;
  }
  return depth;
}

// Mocha-style full title, e.g. "Suite name test name".
function fullTitle(task) {
  const names = [task.name];
  let current = task.suite;
  while (current && current.type !== "file") {
    if (current.name) names.unshift(current.name);
    current = current.suite;
  }
  return names.join(" ");
}

// Report test results to the host process over HTTP.
// The event protocol is identical to the previous mocha-based reporter,
// so `TestHttpReporter` on the host side stays unchanged.
class Reporter {
  constructor() {
    this.config = {
      root: "/",
      setupFiles: [],
      name: undefined,
      passWithNoTests: false,
      testNamePattern: undefined,
      allowOnly: true,
      sequence: { shuffle: false, concurrent: false, seed: 0, hooks: "stack", setupFiles: "parallel" },
      chaiConfig: undefined,
      maxConcurrency: 10,
      testTimeout: __TIMEOUT__,
      hookTimeout: __TIMEOUT__,
      retry: 0,
      includeTaskLocation: false,
      diffOptions: undefined,
      tags: [],
      tagsFilter: undefined,
      strictTags: false,
    };
    this._importDurations = new Map();
  }

  // Called by `startTests` to load each test file.
  // Test files are bundled as ES modules and share this runtime chunk,
  // so `describe`/`it` registrations land in the same suite state.
  async importFile(filepath) {
    const start = performance.now();
    await import("./" + filepath);
    this._importDurations.set(filepath, { start, end: performance.now() });
  }

  getImportDurations() {
    return Object.fromEntries(this._importDurations);
  }

  onCollected(files) {
    send({ type: "start", data: {} });
  }

  onBeforeRunSuite(suite) {
    // The file task is a suite too; skip it and only report named suites.
    if (suite.name && suite.file !== suite) {
      const indents = suiteDepth(suite) + 2;
      dump("  ".repeat(indents - 1) + suite.name + "\n");
      send({ type: "suite", data: { title: suite.name, root: false, indents } });
    }
  }

  onAfterRunSuite(suite) {
    if (suite.name && suite.file !== suite) {
      send({ type: "suite end", data: { title: suite.name, root: false, indents: suiteDepth(suite) + 1 } });
    }
  }

  onBeforeRunTask(test) {
    // Skipped/todo tests never reach `onAfterRunTask` (the runner returns
    // early for them), so report them as pending here.
    if (test.mode === "skip" || test.mode === "todo") {
      const indents = suiteDepth(test) + 3;
      dump("  ".repeat(indents - 1) + "pending  -" + test.name + "\n");
      send({ type: "pending", data: { title: test.name, fulltest: fullTitle(test), indents } });
    }
  }

  onAfterRunTask(test) {
    const state = test.result?.state;
    const indents = suiteDepth(test) + 3;
    const data = {
      title: test.name,
      fulltest: fullTitle(test),
      duration: test.result?.duration,
      indents,
    };

    if (state === "pass") {
      passed++;
      let str = "  ".repeat(indents - 1) + "✔ " + test.name;
      if (test.result?.duration) {
        str += ` (${Math.round(test.result.duration)} ms)`;
      }
      str += "\n";
      dump(str);
      send({ type: "pass", data });
    }
    else if (state === "fail") {
      failed++;
      const error = test.result?.errors?.[0];
      const str = "  ".repeat(indents - 1) + "✘ " + test.name + "\n"
        + "  ".repeat(indents - 1) + "  " + (error?.message ?? "") + "\n\n";
      dump(str);
      send({ type: "fail", data: { ...data, error } });

      if (__ABORT_ON_FAIL__) {
        aborted = true;
        this.cancel("Aborted by abortOnFail");
      }
    }
    else if (state === "skip" || state === "todo") {
      dump("  ".repeat(indents - 1) + "pending  -" + test.name + "\n");
      send({ type: "pending", data });
    }
  }

  onAfterRunFiles(files) {
    // Report collection/run errors that are not attached to a single test,
    // e.g. a test file that failed to import or contains no tests.
    for (const file of files) {
      for (const error of file.result?.errors || []) {
        send({ type: "error", data: { title: error.message } });
        failed++;
      }
    }

    const str = passed + "/" + (passed + failed) + " tests passed"
      + (aborted ? " -- aborting" : "") + "\n";
    dump(str);
    send({ type: "end", data: { passed, failed, aborted, str, indents: 0 } });
  }
}

const testFiles = __TEST_FILES__;

startTests(testFiles, new Reporter())
  .catch((error) => {
    failed++;
    send({ type: "error", data: { title: error.message } });
  })
  .finally(() => {
    // Must exit on Zotero side with code 0, otherwise Zotero will auto-restart
    // and CI will hang. The exit code is determined by the host process from
    // the "end" event.
    if (__EXIT_ON_FINISH__) {
      Zotero.Utilities.Internal.quit(0);
    }
  });
